   "url": "https://www.woshipm.com/ai/6466723.html",
   "summary": "当知识库不再满足于\"找答案\"，腾讯开源的WeKnora把文档解析、知识图谱、Agent沙箱与Skill生态串成一条完整链路。0.8.0版本为每个会话提供持久化运行时，让文件读写、脚本执行与产物生成在受控工作区中完成。本文解析这套框架如何让分散文档真正变成可推理、可执行的知识资产。 一份产品设计手册，可能同时包含文字、表格、流程图；一套企业制度会不断更新；一个研发项目的知识，又往往分散在文档、代码仓库、协作平台和网页里。 当我们把这些资料交给 AI，最常见的期待是“帮我找答案”。但真实工作并不会止于一次问答：AI 能不能读对一张表格？能不能沿着多个文档找到完整线索？当制度更新后，知识库能不能跟着",
