   "id": "tibw3y",
   "title": "「工作大脑」的底层基座：产品经理 AI 工作区搭建指南",
   "url": "https://www.woshipm.com/ai/6436720.html",
   "summary": "AI 已经能超越人类，前提是给它完整的上下文——但这件事比想象中难。一个 10 年产品经理把工作大脑拆成知识库、工作流、复盘三大模块，做成开源项目 PMCockpit，用本地文件夹和 AGENTS.md 让 AI 真正读懂你的项目。本文先讲最核心的知识库搭建：三层目录、索引规则、Git 兜底，不碰向量数据库也能让 AI 拥有持续上下文。 如果把问题说得很清楚、给足上下文和指令，AI 已经超过人类——但”给它完整的上下文和指令”这个前提很难达到。——梁文锋四小时会议 之前发布过一篇《搭建自进化的”工作大脑”》，聊作为一个10年产品经理，是如何把产品工作托管给 AI。发完之后，私信里问得最多的还是",
