   "url": "https://techorange.com/2026/09/17/openai-framework-for-reporting-model-misalignment",
   "summary": "OpenAI 先前預告的 AI 異常行為揭露制度正式出爐。9 月初「Wiki 事件」曝光後，OpenAI 曾表示，過去主要把模型失準（model misalignment）視為研究問題，缺乏固定的公開機制，因此預告將建立新的揭露框架。不到兩週，OpenAI 便正式公布「模型失準事件揭露框架」（Model Misalignment Reporting Framework），並一次公開過去半年觀察到的 6 起異常案例。 延伸閱讀：OpenAI Agent 把德文 Wiki 變留言板，為何他們早就知道卻沒有公開？ 這套制度出現的背景，是外界對 AI 公司究竟掌握多少 Agent（AI 代理）異常活動",
