   "summary": "X 宣布把交易功能整合進社群平台。Elon Musk 旗下 X 近日推出 Cashtag 新功能，美國用戶現在即可透過合作券商，直接從 X 上查看股票資訊並進行交易。首批合作夥伴包括 Interactive Brokers、Moomoo、Gemini、Kraken 與 Coinbase，涵蓋股票證券經紀商及加密貨幣交易平台。 不再只是討論標籤：X 升級 Cashtag 功能，點擊股票代號即可串接券商下單 《TechCrunch》指出，Cashtag 並不是 X 新推出的概念。早在 2008 年，金融社群平台 Stocktwits 就提出以「$」搭配股票代號的用法，方便用戶搜尋特定股票的市場討論",
