   "id": "10shk0p",
   "title": "瑞安航空如何把客服從「成本中心」變成策略資產？AI 每天處理 12 萬則對話、8 成免真人介入",
   "url": "https://techorange.com/2026/09/16/ryanair-ai-customer-chats-without-humans",
   "summary": "歐洲最大的廉航瑞安航空公司（Ryanair）持續擴大 AI 在客服領域的應用。根據 AWS 發布的案例研究，瑞安航空目前每天透過 AI 處理約 12 萬則客服對話，涵蓋 7 種語言，其中約 80% 的對話可在無需人工客服介入的情況下完成。 準確率達 94%、回覆僅需 2.9 秒：瑞安航空導入 AWS 打造 AI 客服系統 瑞安航空這套系統由 AWS 提供雲端與 AI 服務，並與跨國 IT 與雲端技術諮詢公司 Cation Consulting 共同打造，可集中處理行李、退款、訂位及航班異動等主要客服問題。該系統自 2024 年 10 月推出以來，已處理 1,000 萬則客服對話，準確率達 94",
   "date": "2026-09-16T08:43:52.000Z",
